.message-area-header h5 {
    margin: 0;
    font-weight: 700;
}

.channel-desc {
    font-size: 0.8rem;
    color: #666;
}

.message-list {
    flex: 1;
    overflow-y: auto;
    padding: 1rem 1.25rem;
}

.loading-indicator {
    text-align: center;
    padding: 0.5rem;
    color: #888;
    font-size: 0.85rem;
}

/* Message item */
.message-item {
