}

.message-content {
    margin: 0.2rem 0 0.3rem;
    font-size: 0.9rem;
    line-height: 1.4;
}

.message-reactions {
    display: flex;
    gap: 0.35rem;
    flex-wrap: wrap;
    margin-top: 0.25rem;
}

.reaction-badge {
    display: inline-flex;
    align-items: center;
    gap: 3px;
    font-size: 0.8rem;
    padding: 2px 8px;
    border-radius: 12px;
    background: #e8eaf6;
    border: 1px solid #c5cae9;
    cursor: pointer;
    transition: background 0.15s;
}

.reaction-badge:hover {
    background: #c5cae9;
}

.thread-link {
    background: none;
    border: none;
    color: #1976d2;
    font-size: 0.8rem;
    padding: 0;
    cursor: pointer;
    margin-top: 0.2rem;
}

.thread-link:hover {
    text-decoration: underline;
