.thread-header h6 {
    margin: 0;
    font-weight: 700;
}

.btn-close-thread {
    background: none;
    border: none;
    font-size: 1.1rem;
    cursor: pointer;
    color: #666;
    padding: 2px 6px;
    border-radius: 4px;
}

.btn-close-thread:hover {
    background: #e9ecef;
