.chat-layout {
    display: flex;
    height: calc(100vh - 3.5rem);
    overflow: hidden;
}

/* Sidebar */
.chat-sidebar {
    width: 20%;
    min-width: 200px;
    border-right: 1px solid #e0e0e0;
    background: #f8f9fa;
    overflow-y: auto;
}

.channel-list {
    padding: 1rem 0;
}

.channel-list-header {
    padding: 0 1rem;
    margin-bottom: 0.75rem;
    font-weight: 600;
    color: #555;
    text-transform: uppercase;
    font-size: 0.75rem;
    letter-spacing: 0.05em;
}

.channel-item {
    padding: 0.5rem 1rem;
    cursor: pointer;
    border-left: 3px solid transparent;
    transition: background 0.15s;
}

.channel-item:hover {
    background: #e9ecef;
}

.channel-item.active {
    background: #e3f2fd;
    border-left-color: #1976d2;
}

.channel-name-row {
    display: flex;
    align-items: center;
    justify-content: space-between;
}

.channel-name {
    font-weight: 500;
    font-size: 0.9rem;
}

.channel-description {
    font-size: 0.75rem;
    color: #888;
    display: block;
    margin-top: 2px;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.unread-badge {
    background: #1976d2;
    color: white;
    font-size: 0.7rem;
    padding: 1px 6px;
    border-radius: 10px;
    font-weight: 600;
}

/* Main area */
.chat-main {
    flex: 1;
    display: flex;
    flex-direction: column;
    min-width: 0;
}

.chat-main.with-thread {
    flex: 0 0 55%;
}

.message-area {
    display: flex;
    flex-direction: column;
    height: 100%;
}

